import{_ as o,C as a,o as l,c as n,a2 as s,E as r}from"./chunks/framework.BSaF8iZ6.js";const f=JSON.parse('{"title":"Seller Shop Page","description":"","frontmatter":{},"headers":[],"relativePath":"storefront/seller-shop-page.md","filePath":"storefront/seller-shop-page.md","lastUpdated":1789411447000}'),i={name:"storefront/seller-shop-page.md"};function h(p,e,g,c,d,u){const t=a("ImagePopup");return l(),n("div",null,[e[0]||(e[0]=s('<h1 id="seller-shop-page" tabindex="-1">Seller Shop Page <a class="header-anchor" href="#seller-shop-page" aria-label="Permalink to &quot;Seller Shop Page&quot;">​</a></h1><div class="page-roles"><span class="role role--customer">Customer</span><span class="role role--seller">Seller</span></div><p>Every seller has a public shop page with their products, reviews and store policies. It opens at <code>/marketplace/</code> followed by the seller&#39;s slug, for example <code>/marketplace/urban-threads</code>.</p><p>Customers reach it from the <strong>Sold By</strong> link on a product, from the featured sellers, or from a link the seller shares. Sellers open their own with <strong>Visit Shop</strong> in the Seller Panel.</p>',4)),r(t,{src:"/images/seller-shop-page/shop-page.png",alt:"A seller's shop page"}),e[1]||(e[1]=s('<h2 id="the-top-of-the-page" tabindex="-1">The top of the page <a class="header-anchor" href="#the-top-of-the-page" aria-label="Permalink to &quot;The top of the page&quot;">​</a></h2><ul><li>The seller&#39;s banner, logo, business name and address.</li><li>Their star rating and number of reviews.</li><li><strong>Share</strong>, which lists the seller&#39;s social media links.</li><li><strong>Contact</strong>, to send the seller a message by email.</li><li><strong>Report Issue</strong>, for customers who bought from the seller, when the store lets customers report sellers. See <a href="./../moderation/seller-product-flagging">Seller &amp; Product Flagging</a>.</li></ul><p>When the store has <strong>Show Red Flag</strong> switched on, a red flag next to the name means customers have reported this seller more often than the store allows. It counts every report the seller has received.</p><h2 id="contact-the-seller" tabindex="-1">Contact the seller <a class="header-anchor" href="#contact-the-seller" aria-label="Permalink to &quot;Contact the seller&quot;">​</a></h2><ol><li>Click <strong>Contact</strong>.</li><li>Enter your <strong>Name</strong>, <strong>Email</strong>, <strong>Subject</strong> and <strong>Query</strong>.</li><li>Click <strong>Submit</strong>.</li></ol>',5)),r(t,{src:"/images/seller-shop-page/contact-seller.png",alt:"The Contact form on a seller's shop page"}),e[2]||(e[2]=s('<p>You&#39;ll see <strong>Your query has been submitted successfully</strong>. The seller receives your message by email and can reply to your email address. Anyone can use this form, without signing in.</p><p>To keep a conversation with a seller in your account instead, use <a href="./../customers/communications">Communications</a>.</p><h2 id="products" tabindex="-1">Products <a class="header-anchor" href="#products" aria-label="Permalink to &quot;Products&quot;">​</a></h2><p>The <strong>Products</strong> tab lists the products the seller created, with how many there are.</p><ul><li>Use the filters on the left, including a <strong>Price</strong> range, to narrow the list.</li><li>Use <strong>Sort By</strong> to order products from <strong>A-Z</strong>, <strong>Z-A</strong>, newest, oldest, cheapest or most expensive.</li><li>Choose how many to <strong>Show</strong> per page, and switch between grid and list.</li><li>Use <strong>Search for Products</strong> to search this seller&#39;s products.</li><li>Click <strong>Load More</strong> to see more.</li></ul><p>Catalog products the seller sells as their own don&#39;t appear here. Customers find those offers on the product&#39;s own page. See <a href="./shopping-across-sellers">Shopping Across Sellers</a>.</p><h2 id="reviews" tabindex="-1">Reviews <a class="header-anchor" href="#reviews" aria-label="Permalink to &quot;Reviews&quot;">​</a></h2><p>The <strong>Reviews</strong> tab shows the seller&#39;s average rating, how the ratings split across one to five stars, and the five latest approved reviews. When there are five or more, click <strong>View All Reviews</strong> to see the rest.</p><h3 id="review-a-seller" tabindex="-1">Review a seller <a class="header-anchor" href="#review-a-seller" aria-label="Permalink to &quot;Review a seller&quot;">​</a></h3><p>Customers who have ordered from the seller can review them once.</p><ol><li>Sign in to your customer account.</li><li>Open the seller&#39;s shop page and click the <strong>Reviews</strong> tab.</li><li>Click <strong>Write a Review</strong>.</li><li>Choose a star rating, and enter a <strong>Title</strong> and <strong>Comment</strong>.</li><li>Click <strong>Submit</strong>.</li></ol>',11)),r(t,{src:"/images/seller-shop-page/write-review.png",alt:"The Write a Review form for a seller"}),e[3]||(e[3]=s('<p>You&#39;ll see <strong>Seller Reviewed successfully</strong>. Your review appears once the store admin approves it. See <a href="./../moderation/rating-management">Reviews &amp; Ratings</a>.</p><h2 id="about" tabindex="-1">About <a class="header-anchor" href="#about" aria-label="Permalink to &quot;About&quot;">​</a></h2><p>The <strong>About</strong> tab shows the seller&#39;s business description, any other details the store shares publicly, and their <strong>Shipping Policy</strong>, <strong>Return Policy</strong> and <strong>Privacy Policy</strong> when the seller has written them.</p>',3)),r(t,{src:"/images/seller-shop-page/about-tab.png",alt:"The About tab with the seller's policies"}),e[4]||(e[4]=s('<p>Sellers edit all of this on <a href="./../seller-panel/manage-profile">Manage Profile</a>.</p><h2 id="when-a-shop-page-isn-t-available" tabindex="-1">When a shop page isn&#39;t available <a class="header-anchor" href="#when-a-shop-page-isn-t-available" aria-label="Permalink to &quot;When a shop page isn&#39;t available&quot;">​</a></h2><p>A shop page can&#39;t be opened when:</p><ul><li>the store doesn&#39;t make seller shops public (<strong>Show Publicly</strong> in <a href="./../configuration/sellers">Sellers settings</a>);</li><li>the seller isn&#39;t approved, or is suspended;</li><li>the seller doesn&#39;t sell on the channel you&#39;re browsing;</li><li>the store uses subscription plans and the seller has no active plan;</li><li>the marketplace is switched off.</li></ul>',4))])}const _=o(i,[["render",h]]);export{f as __pageData,_ as default};
